  .mcell .more:hover{color:var(--text)}
  .mcell .clickzone{position:absolute;inset:0;z-index:0}

  /* ── agenda ────────────────────────────────────────────────────────── */
  .agenda{overflow:auto;padding:8px 16px 60px;flex:1}
  .ag-day{margin-top:14px}
  .ag-day h4{position:sticky;top:0;background:var(--bg);margin:0;padding:6px 0;font-size:11px;
    text-transform:uppercase;letter-spacing:.08em;color:var(--faint);z-index:2;
    display:flex;gap:8px;align-items:center}
  .ag-day h4 .line{flex:1;height:1px;background:var(--border)}
  .ag-day.today h4{color:var(--primary)}
  .ag-row{display:flex;gap:12px;align-items:flex-start;padding:8px 10px;border-radius:10px;
    border:1px solid transparent;cursor:pointer}
  .ag-row:hover{background:var(--raised);border-color:var(--border)}
  .ag-time{width:96px;flex:0 0 auto;font-family:var(--mono);font-size:11px;color:var(--muted);padding-top:2px}
  .ag-main{flex:1;min-width:0}
  .ag-title{font-weight:600;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
  .ag-sub{font-size:11px;color:var(--faint);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .ag-cal{display:inline-flex;align-items:center;gap:5px;font-size:10px;color:var(--muted)}
  .ag-cal i{width:7px;height:7px;border-radius:50%;display:block}
  .empty{padding:40px;text-align:center;color:var(--faint)}

  /* ── popovers / modals ─────────────────────────────────────────────── */
  #detail{position:fixed;z-index:60;width:330px;background:var(--overlay);border:1px solid var(--border-strong);
    border-radius:14px;box-shadow:0 24px 60px rgba(0,0,0,.55);display:none;overflow:hidden}
  #detail.open{display:block}
  #detail .bar{height:5px;background:var(--cc)}
  #detail .body{padding:14px}
  #detail h3{margin:0 0 2px;font-size:15px;line-height:1.3}
  #detail .when{font-size:12px;color:var(--muted);margin-bottom:10px}
  #detail .field{font-size:12px;color:var(--muted);display:flex;gap:8px;margin-top:8px;line-height:1.5}
  #detail .field span:first-child{width:16px;flex:0 0 auto;text-align:center;opacity:.7}
  #detail .calchips{display:flex;gap:4px;flex-wrap:wrap;margin-top:10px}
  #detail .calchip{display:inline-flex;align-items:center;gap:5px;font-size:10px;padding:2px 7px;
    border-radius:999px;border:1px solid var(--border);color:var(--muted)}
  #detail .calchip i{width:6px;height:6px;border-radius:50%;display:block}
  #detail .actions{display:flex;gap:6px;justify-content:flex-end;padding:10px 14px;
    border-top:1px solid var(--border);background:var(--raised)}

  .backdrop{position:fixed;inset:0;background:rgba(0,0,0,.55);backdrop-filter:blur(2px);
    z-index:70;display:none;align-items:center;justify-content:center;padding:20px}
  .backdrop.open{display:flex}
  .modal{width:min(560px,100%);max-height:90vh;overflow:auto;background:var(--overlay);
    border:1px solid var(--border-strong);border-radius:16px;box-shadow:0 30px 80px rgba(0,0,0,.6)}
  .modal header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;
    border-bottom:1px solid var(--border)}
  .modal header h2{margin:0;font-size:15px}
  .modal .content{padding:16px 18px;display:flex;flex-direction:column;gap:12px}
  .modal footer{display:flex;gap:8px;justify-content:flex-end;padding:12px 18px;
    border-top:1px solid var(--border);background:var(--raised)}
  .row{display:flex;gap:10px}
  .row > *{flex:1;min-width:0}
  label.f{display:flex;flex-direction:column;gap:4px;font-size:11px;color:var(--muted);font-weight:600}
  label.f input,label.f select,label.f textarea{
    background:var(--sunken);border:1px solid var(--border-strong);border-radius:8px;
    padding:8px 10px;font-size:13px;color:var(--text);font-weight:400;width:100%;
  }
  label.f input:focus,label.f select:focus,label.f textarea:focus{outline:2px solid var(--primary);outline-offset:-1px}
  label.f textarea{resize:vertical;min-height:58px}
  .checkbox{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}
  .checkbox input{width:15px;height:15px;accent-color:var(--primary)}
  .calpick{display:flex;flex-wrap:wrap;gap:6px}
  .calpick label{display:inline-flex;align-items:center;gap:6px;font-size:11px;padding:5px 9px;
    border:1px solid var(--border-strong);border-radius:999px;cursor:pointer;color:var(--muted)}
  .calpick label.on{border-color:var(--cc);background:color-mix(in oklch,var(--cc) 22%, transparent);color:var(--text)}
  .calpick input{display:none}
  .calpick i{width:7px;height:7px;border-radius:50%;display:block}
  .swatches{display:flex;gap:6px;flex-wrap:wrap}
  .swatches button{width:22px;height:22px;border-radius:50%;border:2px solid transparent}
  .swatches button.on{border-color:var(--text)}
  .err{color:var(--error);font-size:11px;min-height:0}

  /* ── notifications ─────────────────────────────────────────────────── */
  #notif-panel{
    position:fixed;top:52px;right:12px;width:390px;max-height:min(70vh,560px);z-index:80;
    background:var(--overlay);border:1px solid var(--border-strong);border-radius:14px;
    box-shadow:0 24px 60px rgba(0,0,0,.55);display:none;flex-direction:column;overflow:hidden;
  }
  #notif-panel.open{display:flex}
  #notif-panel header{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--border)}
  #notif-panel header h3{margin:0;font-size:13px;flex:1}
  .tabs{display:flex;gap:2px;padding:8px 12px 0}
  .tabs button{font-size:11px;padding:4px 9px;border-radius:7px;color:var(--muted)}
  .tabs button[aria-selected="true"]{background:var(--raised);color:var(--text);font-weight:600}
  .nlist{overflow:auto;padding:6px}
  .nitem{display:flex;gap:9px;padding:9px;border-radius:9px;cursor:pointer;align-items:flex-start}
  .nitem:hover{background:var(--raised)}
  .nitem .ico{width:20px;flex:0 0 auto;text-align:center;font-size:12px;padding-top:1px}
  .nitem .txt{flex:1;min-width:0}
  .nitem .ttl{font-size:12px;font-weight:600;display:flex;gap:6px;align-items:center}
  .nitem .sub{font-size:11px;color:var(--faint);margin-top:2px;line-height:1.45}
  .nitem .when{font-size:10px;color:var(--faint);font-family:var(--mono);white-space:nowrap}
  .nitem.unread .ttl::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--primary);flex:0 0 auto}
  .nitem.missed{background:color-mix(in oklch,var(--warning) 9%, transparent)}
  .nfooter{border-top:1px solid var(--border);padding:8px 12px;display:flex;gap:8px;justify-content:space-between}

  /* ── toasts / reminder popups ──────────────────────────────────────── */
  #toasts{position:fixed;right:16px;bottom:16px;z-index:90;display:flex;flex-direction:column;gap:10px;
    width:360px;max-width:calc(100vw - 32px)}
  .toast{background:var(--overlay);border:1px solid var(--border-strong);border-radius:14px;
    box-shadow:0 20px 50px rgba(0,0,0,.6);overflow:hidden;animation:slidein .18s ease-out}
  @keyframes slidein{from{transform:translateY(12px);opacity:0}to{transform:translateY(0);opacity:1}}
  .toast .bar{height:4px;background:var(--primary)}
  .toast .in{padding:12px 14px}
  .toast .kick{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:var(--primary);
    font-weight:700;display:flex;gap:6px;align-items:center}
  .toast h4{margin:6px 0 2px;font-size:14px}
  .toast p{margin:0;font-size:12px;color:var(--muted);line-height:1.45}
  .toast .acts{display:flex;gap:6px;padding:0 14px 12px}
  .toast .acts .btn{font-size:11px;padding:5px 10px}
  .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
</style>
</head>
<body>
<div id="app">
  <div class="topbar">
    <div class="brand"><span class="dot"></span>codx-junior <small>calendar</small></div>
    <button class="btn" id="btn-today">Today</button>
    <button class="btn icon" id="btn-prev" title="Previous (←)">‹</button>
    <button class="btn icon" id="btn-next" title="Next (→)">›</button>
    <div id="range-label">—</div>
    <div class="spacer"></div>
    <div class="sim" title="Simulated clock: reminders fire from this clock, not the real one">
      <span>sim</span><b id="sim-clock">--:--</b>
      <button class="btn" id="sim-play" title="Toggle time flow">❚❚</button>
      <button class="btn" id="sim-next" title="Jump to the next pending reminder">⏭ next</button>
      <button class="btn" id="sim-reset" title="Back to real time">now</button>
    </div>
    <div class="seg" role="tablist" id="view-switch">
      <button role="tab" data-view="month" aria-selected="true">Month</button>
      <button role="tab" data-view="week" aria-selected="false">Week</button>
      <button role="tab" data-view="day" aria-selected="false">Day</button>
      <button role="tab" data-view="agenda" aria-selected="false">Agenda</button>
    </div>
    <button class="bell" id="btn-bell" title="Notifications">
      <span aria-hidden="true">🔔</span>
      <span class="badge" id="notif-badge" hidden>0</span>
    </button>
    <button class="btn primary" id="btn-new">+ New event</button>
  </div>

  <aside>
    <button class="create" id="btn-create"><span class="plus">+</span> Create</button>
    <div class="mini" id="mini"></div>
    <div>
      <div class="section-title">My calendars</div>
      <div class="cal-list" id="cal-list"></div>
      <button class="cal-row" id="btn-add-cal" style="color:var(--primary);font-weight:600">
        <span style="width:14px;text-align:center">+</span> Add calendar
      </button>
    </div>
    <div>
      <div class="section-title">Other calendars</div>
      <div class="cal-list" id="cal-list-other"></div>
    </div>
    <div class="spacer"></div>
    <details class="help">
      <summary>About this prototype</summary>
      <ul>
        <li>Open a cell to create an event; click a chip for details.</li>
        <li><b>Work · Personal · Team</b> are editable calendars. <b>codx-junior</b> is a read-only
          projection of tasks, runs and meets.</li>
        <li>“Sprint 42 review” lives in <b>two</b> calendars: the chip shows a two-tone bar and both dots.</li>
        <li>Reminders fire from the <b>simulated clock</b>: use ❚❚ / ⏭ next.</li>
        <li>Keys: <kbd>n</kbd> new · <kbd>t</kbd> today · <kbd>m</kbd><kbd>w</kbd><kbd>d</kbd><kbd>a</kbd>
          views · <kbd>←</kbd><kbd>→</kbd> move · <kbd>Esc</kbd> close.</li>
        <li>Data is demo data kept in localStorage. <button class="btn ghost" id="btn-reset"
          style="padding:0;font-size:11px;color:var(--error);text-decoration:underline">Reset demo data</button></li>
      </ul>
    </details>
  </aside>

  <main id="view"></main>
</div>

<div id="detail" role="dialog" aria-label="Event details"></div>

<div class="backdrop" id="backdrop">
  <div class="modal" id="modal" role="dialog" aria-modal="true"></div>
</div>

<div id="notif-panel" role="dialog" aria-label="Notifications"></div>

<div id="toasts" aria-live="polite"></div>
<div class="sr" id="sr-status" aria-live="polite"></div>

<script>
"use strict";
/* ════════════════════════════════════════════════════════════════════════
   0. tiny date layer
   The prototype stores NAIVE LOCAL iso strings ("2026-02-10T09:00") so the
   demo is stable in any timezone. The real API stores UTC + the calendar's
   timezone and returns occurrences (analysis §8).
   ════════════════════════════════════════════════════════════════════════ */
const MIN = 60000, HOUR = 3600000, DAY = 86400000;
const DOW = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
const DOW_LONG = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
const MON = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const pad2 = n => String(n).padStart(2, "0");
const pdate = iso => iso ? new Date(iso) : null;                 // naive-local iso -> Date
function isoLocal(d){
  return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}T${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
}
const dateKey = d => `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`;
const startOfDay = d => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const addDays = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate()+n, d.getHours(), d.getMinutes());
const addMonths = (d, n) => new Date(d.getFullYear(), d.getMonth()+n, 1);
function startOfWeek(d){ const s = startOfDay(d); const w = (s.getDay()+6)%7; return addDays(s, -w); }
const sameDay = (a,b) => a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate();
const daysBetween = (a,b) => Math.round((startOfDay(b) - startOfDay(a))/DAY);
function fmtTime(d){ return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`; }
function fmtTimeRange(a,b){ return `${fmtTime(a)} – ${fmtTime(b)}`; }
function fmtDay(d){ return `${DOW_LONG[(d.getDay()+6)%7]}, ${d.getDate()} ${MON[d.getMonth()]} ${d.getFullYear()}`; }
function fmtShort(d){ return `${DOW[(d.getDay()+6)%7]} ${d.getDate()} ${MON[d.getMonth()].slice(0,3)}`; }

/* ════════════════════════════════════════════════════════════════════════
   1. demo data  (mirrors design/06-calendar/03-fixtures/calendar-fixture.json)
   ════════════════════════════════════════════════════════════════════════ */
const STORE_KEY = "codx-calendar-prototype-v2";

function seed(){
  const today = startOfDay(new Date());
  const now = new Date();
  const at = (dayOffset, h, m=0, durMin=60) => {
    const s = new Date(today.getFullYear(), today.getMonth(), today.getDate()+dayOffset, h, m);
    const e = new Date(s.getTime() + durMin*MIN);
    return { start: isoLocal(s), end: isoLocal(e) };
  };
  const soon = new Date(now.getTime() + 9*MIN);
  soon.setSeconds(0,0);
  const soonEnd = new Date(soon.getTime() + 30*MIN);

  const calendars = [
    { id:"cal_work",     name:"Work",              color:"#CC0099", kind:"personal", read_only:false, visible:true,
      default_reminders:[{channel:"popup",minutes_before:10}] },
    { id:"cal_personal", name:"Personal",          color:"#4696DC", kind:"personal", read_only:false, visible:true,
      default_reminders:[{channel:"popup",minutes_before:30}] },
    { id:"cal_team",     name:"Team — Platform",   color:"#3CB450", kind:"team",     read_only:false, visible:true,
      default_reminders:[{channel:"popup",minutes_before:10}] },
    { id:"cal_codx",     name:"codx-junior",       color:"#FFB428", kind:"system",   read_only:true,  visible:true,
      default_reminders:[] },
    { id:"cal_ics",      name:"Holidays (ICS)",    color:"#7C5CFF", kind:"external", read_only:true,  visible:false,
      default_reminders:[] }
  ];

  const ev = (o) => Object.assign({
    calendar_ids:["cal_work"], description:"", location:"", all_day:false, recurrence:null,
    reminders:[], status:"confirmed", visibility:"default", source:"native", refs:{},
    guests:[], created_by:"alice", revision:1
  }, o);

  const events = [
    ev({ id:"evt_standup", calendar_ids:["cal_team","cal_work"], title:"Daily standup",
         start:at(0,9,15,15).start, end:at(0,9,15,15).end,
         location:"Meet · platform", guests:["marta","jordi"], source:"meet",
         refs:{ meet_id:"9f2a41" }, reminders:[{channel:"popup",minutes_before:5}],
         recurrence:{ rrule:"FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR;UNTIL:" + isoLocal(addDays(today,45)).replace(/[-:]/g,"").slice(0,8) + "T235959Z" } }),

    ev({ id:"evt_spec", calendar_ids:["cal_work"], title:"Spec review — calendar manager",
         start:isoLocal(soon), end:isoLocal(soonEnd),
         description:"Walk through storage + reminders sections before M0.",
         location:"Meet /meet/9f2a", guests:["marta"],
         reminders:[{channel:"popup",minutes_before:15},{channel:"popup",minutes_before:0}] }),

    ev({ id:"evt_sprint", calendar_ids:["cal_codx","cal_work"], title:"Sprint 42 review",
         start:at(1,16).start, end:at(1,17).end, source:"task",
         refs:{ chat_id:"chat_7fd2", project_id:"codx-junior-platform", task_status:"doing" },
         description:"Task card in board “Delivery” · column “In progress”.",
         reminders:[{channel:"popup",minutes_before:10}],
         override_color:null }),

    ev({ id:"evt_1on1", calendar_ids:["cal_work","cal_personal"], title:"1:1 with Marta",
         start:at(2,12).start, end:at(2,12,30).end, guests:["marta"],
         description:"Growth plan + Q2 goals.", reminders:[{channel:"popup",minutes_before:10}] }),

    ev({ id:"evt_offsite", calendar_ids:["cal_work"], title:"Team offsite",
         start:at(10,0).start, end:at(12,23,59).end, all_day:true, location:"Girona",
         description:"Two days out of the office.", reminders:[] }),

    ev({ id:"evt_flight", calendar_ids:["cal_personal"], title:"Flight to Lisbon",
         start:at(8,7,30).start, end:at(8,10,5).end, location:"BCN → LIS",
         reminders:[{channel:"popup",minutes_before:180},{channel:"popup",minutes_before:60}] }),

    ev({ id:"evt_due", calendar_ids:["cal_codx"], title:"Fix onboarding copy",
         start:isoLocal(addDays(today,-1))+"T09:00", end:isoLocal(addDays(today,-1))+"T09:30",
         all_day:true, source:"task", refs:{ chat_id:"chat_91ab", task_status:"todo" },
         description:"Due date marker — read-only, managed by the Task Manager." }),

    ev({ id:"evt_run", calendar_ids:["cal_codx"], title:"Run: autonomous-profiles (7 steps)",
         start:at(0,11,30,90).start, end:at(0,11,30,90).end, source:"orchestration",
         refs:{ run_id:"run_a91f", run_status:"running" },
         description:"2/7 steps done · budget 60 % left." }),

    ev({ id:"evt_retro", calendar_ids:["cal_team"], title:"Team retro",
         start:at(6,15).start, end:at(6,16).end, guests:["marta","jordi","ana"],
         reminders:[{channel:"popup",minutes_before:10}],
         recurrence:{ rrule:"FREQ=MONTHLY;INTERVAL=1;UNTIL:" + isoLocal(addDays(today,180)).replace(/[-:]/g,"").slice(0,8) + "T235959Z" } }),

    ev({ id:"evt_release", calendar_ids:["cal_work","cal_codx"], title:"Release v2.4 window",
         start:at(5,9,0,180).start, end:at(5,9,0,180).end, source:"task",
         refs:{ chat_id:"chat_3c11", task_status:"todo" },
         description:"Freeze + smoke tests. Read-only: change the task to move it." }),

    ev({ id:"evt_holiday", calendar_ids:["cal_ics"], title:"Bank holiday",
         start:isoLocal(addDays(today,14))+"T00:00", end:isoLocal(addDays(today,15))+"T00:00",
         all_day:true, source:"external", description:"Imported from an ICS feed (read-only)." })
  ];

  const notifications = [
    { id:"n1", kind:"system", title:"Task moved to In progress", at:Date.now()-25*MIN,
      body:"“Sprint 42 review” · board Delivery", read:false },
    { id:"n2", kind:"system", title:"Run completed", at:Date.now()-3*HOUR,
      body:"Orchestration run “wiki-refresh” finished · 4 steps, 1.2 cxjcoins", read:true }
  ];

  return { calendars, events, notifications, delivered:{}, snoozes:{} };
}

/* ════════════════════════════════════════════════════════════════════════
   2. state
   ════════════════════════════════════════════════════════════════════════ */
const state = {
  view: "month",
  cursor: startOfDay(new Date()),
  now: Date.now(),
  speed: 60,             // 60× so reminders are observable; 0 = paused
  calendars: [], events: [], notifications: [],
  delivered: {}, snoozes: {},
  detail: null, editing: null, notifTab: "all", notifOpen: false
};

const $ = s => document.querySelector(s);
const el = (tag, cls, html) => { const n = document.createElement(tag); if (cls) n.className = cls; if (html != null) n.innerHTML = html; return n; };
const esc = s => String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));

function load(){
  let data = null;
  try { data = JSON.parse(localStorage.getItem(STORE_KEY) || "null"); } catch(e){ data = null; }
  if (!data || !data.calendars) data = seed();
  state.calendars = data.calendars;
  state.events = data.events;
  state.notifications = data.notifications || [];
  state.delivered = data.delivered || {};
  state.snoozes = data.snoozes || {};
}
function save(){
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify({
      calendars: state.calendars, events: state.events,
      notifications: state.notifications.slice(0,60),
      delivered: state.delivered, snoozes: state.snoozes
    }));
  } catch(e){ /* quota: prototype only */ }
}
const calById = id => state.calendars.find(c => c.id === id) || null;
const isVisible = ev => ev.calendar_ids.some(id => { const c = calById(id); return c && c.visible; });
const primaryCal = ev => calById(ev.calendar_ids[0]) || { color:"#888", name:"—" };

/* ════════════════════════════════════════════════════════════════════════
   3. recurrence + occurrence expansion  (bounded, prototype-grade)
   ════════════════════════════════════════════════════════════════════════ */
function parseRRule(str){
  const out = { freq:"DAILY", interval:1, byday:null, until:null, count:null };
  if (!str) return out;
  const map = { FREQ:v=>out.freq=v, INTERVAL:v=>out.interval=Math.max(1,parseInt(v,10)||1),
                BYDAY:v=>out.byday=v.split(","), UNTIL:v=>out.until=v, COUNT:v=>out.count=parseInt(v,10), };
  str.split(";").forEach(part => { const [k,v] = part.split("="); if (map[k]) map[k](v); });
  return out;
}
const WD = { SU:0, MO:1, TU:2, WE:3, TH:4, FR:5, SA:6 };

function eventOccurrences(ev, rangeStart, rangeEnd){
  const s0 = pdate(ev.start), e0 = pdate(ev.end);
  if (!s0 || !e0) return [];
  const dur = Math.max(MIN, e0 - s0);
  const out = [];
  const push = (start) => out.push({
    key: ev.id + "|" + isoLocal(start),
    event: ev, start, end: new Date(start.getTime() + dur),
    calendar_ids: ev.calendar_ids, source: ev.source, refs: ev.refs || {},
    all_day: !!ev.all_day, read_only: ev.calendar_ids.every(id => (calById(id)||{}).read_only)
  });

  if (!ev.recurrence || !ev.recurrence.rrule){
    if (s0 < rangeEnd && e0 > rangeStart) push(s0);
    return out;
  }

  const rule = parseRRule(ev.recurrence.rrule);
  const until = rule.until
    ? new Date(+rule.until.slice(0,4), +rule.until.slice(4,6)-1, +rule.until.slice(6,8), 23, 59)
    : null;
  // Walk day by day over the window (+alignment), the matcher is order-independent.
  const from = Math.max(startOfDay(s0).getTime(), rangeStart.getTime() - dur - 32*DAY);
  const to   = Math.min(rangeEnd.getTime(), until ? until.getTime() : rangeEnd.getTime());
  let generated = 0, guard = 0;
  for (let t = from; t <= to && guard < 1200; t += DAY, guard++){
    const d = new Date(t);
    const diff = daysBetween(s0, d);
    if (diff < 0) continue;
    const dow = (d.getDay()+6)%7;                       // 0 = Monday
    let hit = false;
    if (rule.freq === "DAILY")       hit = diff % rule.interval === 0;
    else if (rule.freq === "WEEKLY") hit = Math.floor(diff/7) % rule.interval === 0 &&
                                            (!rule.byday || rule.byday.includes(Object.keys(WD).find(k => WD[k] === d.getDay())));
    else if (rule.freq === "MONTHLY"){ const md = (d.getFullYear()-s0.getFullYear())*12 + (d.getMonth()-s0.getMonth());
                                        hit = md % rule.interval === 0 && d.getDate() === s0.getDate(); }
    if (!hit) continue;
    generated++;
    if (rule.count && generated > rule.count) break;
    const start = new Date(d.getFullYear(), d.getMonth(), d.getDate(), s0.getHours(), s0.getMinutes());
    const end = new Date(start.getTime() + dur);
    if (start < rangeEnd && end > rangeStart) push(start);
  }
  return out;
}

function occurrencesBetween(from, to, opts){
  const includeHidden = opts && opts.includeHidden;
  let occs = [];
  for (const ev of state.events){
    if (!includeHidden && !isVisible(ev)) continue;
    occs = occs.concat(eventOccurrences(ev, from, to));
  }
  return occs.sort((a,b) => a.start - b.start);
}

/* ════════════════════════════════════════════════════════════════════════
   4. notifications + reminders
   ════════════════════════════════════════════════════════════════════════ */
function pushNotification(n){
  state.notifications.unshift(Object.assign({ id:"n_" + Math.random().toString(36).slice(2,9),
    at:Date.now(), read:false, kind:"system" }, n));
  if (state.notifications.length > 80) state.notifications.length = 80;
  renderBell(); renderNotifPanel(); save();
}
const unreadCount = () => state.notifications.filter(n => !n.read).length;

function renderBell(){
  const badge = $("#notif-badge"), n = unreadCount();
  badge.hidden = n === 0;
  badge.textContent = n > 99 ? "99+" : String(n);
}

function remindersOf(ev, occ){
  if (occ.read_only) return ev.reminders || [];
  const list = (ev.reminders || []).slice();
  if (!list.length){
    const cal = primaryCal(ev);
    (cal.default_reminders || []).forEach(r => list.push(r));
  }
  return list;
}

// A trigger older than this is reported as "missed" in the notification centre
// instead of popping a toast: analysis §7.2 — the centre is the record, the popup
// is for the present. Without it, catching up after a closed tab showed a storm.
const MISSED_AFTER_MS = 10*MIN;

/** Fires every simulated minute. Mirrors the server tick (analysis §7). */
function checkReminders(catchUpMs){
  const now = state.now;
  const lookBack = catchUpMs || 0;
  const occs = occurrencesBetween(new Date(now - 6*HOUR), new Date(now + 3*DAY), { includeHidden:true });
  for (const occ of occs){
    const keys = [];
    for (const r of remindersOf(occ.event, occ)){
      const trig = occ.start.getTime() - (r.minutes_before||0)*MIN;
      const key = `${occ.event.id}|${isoLocal(occ.start)}|${r.minutes_before}`;
      if (state.delivered[key]) continue;
      if (trig <= now && trig >= now - lookBack){
        keys.push({ key, r, missed: (now - trig) > MISSED_AFTER_MS });
      }
    }
    // snnooze re-fires
    const skey = `${occ.event.id}|${isoLocal(occ.start)}`;
    if (state.snoozes[skey] && state.snoozes[skey].at <= now){
      delete state.snoozes[skey];
      fireReminder(occ, { minutes_before:0, snoozed:true });
    }
    for (const { key, r, missed } of keys){
      state.delivered[key] = new Date(now).toISOString();
      fireReminder(occ, r, missed);
    }
  }
  pruneDelivered();
  save();
}

function pruneDelivered(){
  const limit = Date.now() - 30*DAY;
  Object.keys(state.delivered).forEach(k => {
    if (new Date(state.delivered[k]).getTime() < limit) delete state.delivered[k];
  });
}

function fireReminder(occ, r, missed){
  const ev = occ.event;
  const when = occ.all_day ? "all day" : fmtTimeRange(occ.start, occ.end);
  pushNotification({
    kind:"reminder", title:ev.title, body:`${when} · ${primaryCal(ev).name}`,
    eventId:ev.id, occurrenceKey:occ.key, minutesBefore:r.minutes_before, missed:!!missed
  });
  if (!missed) showToast(occ, r);
  $("#sr-status").textContent = `Reminder: ${ev.title} at ${when}`;
}

function showToast(occ, r){
  const ev = occ.event, cal = primaryCal(ev);
  const when = occ.all_day ? "all day" : fmtTimeRange(occ.start, occ.end);
  const lead = r.snoozed ? "Snoozed reminder" : (r.minutes_before === 0 ? "Starting now" : `In ${r.minutes_before} min`);
  const t = el("div", "toast");
  t.style.setProperty("--cc", cal.color);
  t.innerHTML = `
    <div class="bar" style="background:${cal.color}"></div>
    <div class="in">
      <div class="kick" style="color:${cal.color}">🔔 ${esc(lead)}</div>
      <h4>${esc(ev.title)}</h4>
      <p>${esc(when)}${ev.location ? " · " + esc(ev.location) : ""}</p>
    </div>
    <div class="acts">
      <button class="btn" data-act="open">Open</button>
      <button class="btn" data-act="snooze">Snooze 5 min</button>
      <button class="btn danger" data-act="dismiss">Dismiss</button>
    </div>`;
  const close = () => { t.remove(); };
  t.querySelector('[data-act="open"]').onclick = () => { close(); openDetail(occ); };
  t.querySelector('[data-act="snooze"]').onclick = () => {
    state.snoozes[`${ev.id}|${isoLocal(occ.start)}`] = { at: state.now + 5*MIN };
    pushNotification({ kind:"system", title:"Reminder snoozed 5 min", body:ev.title });
    save(); close();
  };
  t.querySelector('[data-act="dismiss"]').onclick = close;
  $("#toasts").appendChild(t);
  setTimeout(() => { if (t.isConnected) close(); }, 45000);
}

function renderNotifPanel(){
  const p = $("#notif-panel");
  const items = state.notifications.filter(n => state.notifTab === "all" || n.kind === state.notifTab);
  p.innerHTML = `
    <header>
      <h3>Notifications</h3>
      <button class="btn icon" data-act="close" title="Close">✕</button>
    </header>
    <div class="tabs" id="ntabs">
      <button data-tab="all" aria-selected="${state.notifTab==="all"}">All</button>
      <button data-tab="reminder" aria-selected="${state.notifTab==="reminder"}">Reminders</button>
      <button data-tab="system" aria-selected="${state.notifTab==="system"}">System</button>
    </div>
    <div class="nlist">
      ${items.length ? items.map(n => `
        <div class="nitem ${n.read ? "" : "unread"} ${n.missed ? "missed" : ""}" data-id="${n.id}">
          <div class="ico">${n.kind === "reminder" ? "🔔" : "⚡"}</div>
          <div class="txt">
            <div class="ttl">${esc(n.title || "")}${n.missed ? ' <span class="tag">missed</span>' : ""}</div>
            <div class="sub">${esc(n.body || "")}</div>
          </div>
          <div class="when">${fmtTime(new Date(n.at))}</div>
        </div>`).join("") : `<div class="empty">No ${state.notifTab === "all" ? "" : state.notifTab + " "}notifications</div>`}
    </div>
    <div class="nfooter">
      <button class="btn" data-act="readall">Mark all read</button>
      <button class="btn danger" data-act="clear">Clear</button>
    </div>`;

  p.querySelector('[data-act="close"]').onclick = () => toggleNotif(false);
  p.querySelectorAll("#ntabs button").forEach(b => b.onclick = () => { state.notifTab = b.dataset.tab; renderNotifPanel(); });
  p.querySelectorAll(".nitem").forEach(node => node.onclick = () => {
    const n = state.notifications.find(x => x.id === node.dataset.id);
    if (!n) return;
    n.read = true; renderBell(); renderNotifPanel(); save();
    if (n.eventId){
      const ev = state.events.find(e => e.id === n.eventId);
      if (ev) openDetail({ event:ev, start:pdate(ev.start), end:pdate(ev.end),
        calendar_ids:ev.calendar_ids, all_day:ev.all_day, source:ev.source, refs:ev.refs||{},
        read_only:ev.calendar_ids.every(id => (calById(id)||{}).read_only) });
    }
  });
  p.querySelector('[data-act="readall"]').onclick = () => {
    state.notifications.forEach(n => n.read = true); renderBell(); renderNotifPanel(); save();
  };
  p.querySelector('[data-act="clear"]').onclick = () => {
    state.notifications = state.notifications.filter(n => !n.read); renderBell(); renderNotifPanel(); save();
  };
}
function toggleNotif(force){
  state.notifOpen = force === undefined ? !state.notifOpen : force;
  $("#notif-panel").classList.toggle("open", state.notifOpen);
  if (state.notifOpen) renderNotifPanel();
}

/* ════════════════════════════════════════════════════════════════════════
   5. rendering — sidebar
   ════════════════════════════════════════════════════════════════════════ */
function renderSidebar(){
  const mine = state.calendars.filter(c => c.kind !== "system" && c.kind !== "external");
  const other = state.calendars.filter(c => c.kind === "system" || c.kind === "external");
  const row = c => {
    const count = state.events.filter(e => e.calendar_ids.includes(c.id)).length;
    const n = el("button", "cal-row" + (c.read_only ? " readonly" : ""));
    n.style.setProperty("--cc", c.color);
    n.innerHTML = `
      <span class="cal-check ${c.visible ? "" : "off"}"><svg width="9" height="9" viewBox="0 0 10 10">
        <path d="M1 5.2 L3.7 8 L9 2.2" fill="none" stroke="#101114" stroke-width="2"
          stroke-linecap="round" stroke-linejoin="round"/></svg></span>
      <span class="cal-name">${esc(c.name)}</span>
      ${c.read_only ? '<span class="tag ro">ro</span>' : ""}
      <span class="meta">${count}</span>`;
    n.querySelector(".cal-check").onclick = ev => {
      ev.stopPropagation();
      c.visible = !c.visible; save(); renderAll();
    };
    n.onclick = () => { if (!c.read_only) openCalendarEditor(c); };
    return n;
  };
  const list = $("#cal-list"), olist = $("#cal-list-other");
  list.innerHTML = ""; olist.innerHTML = "";
  mine.forEach(c => list.appendChild(row(c)));
  other.forEach(c => olist.appendChild(row(c)));
}

function renderMini(){
  const c = state.cursor;
  const first = new Date(c.getFullYear(), c.getMonth(), 1);
  const gridStart = startOfWeek(first);
  const html = [`<div class="mini-head">
      <span class="mini-title">${MON[c.getMonth()]} ${c.getFullYear()}</span>
      <span><button class="btn ghost" data-nav="-1" style="padding:0 6px">‹</button>
      <button class="btn ghost" data-nav="1" style="padding:0 6px">›</button></span>
    </div>`,
    '<div class="mini-grid">',
    DOW.map(d => `<div class="dow">${d[0]}</div>`).join("")].join("");
  let out = html;
  for (let i = 0; i < 42; i++){
    const d = addDays(gridStart, i);
    const other = d.getMonth() !== c.getMonth();
    const today = sameDay(d, new Date());
    const cur = sameDay(d, c);
    const occ = occurrencesBetween(startOfDay(d), new Date(startOfDay(d).getTime() + DAY));
    const colors = [...new Set(occ.map(o => primaryCal(o.event).color))].slice(0,3);
    out += `<button class="mini-day ${other ? "other" : ""} ${today ? "today" : ""} ${cur && !today ? "cursor" : ""}"
      data-day="${dateKey(d)}">${d.getDate()}
      <span class="mini-dots">${colors.map(col => `<i style="background:${col}"></i>`).join("")}</span></button>`;
  }
  out += "</div>";
  const node = $("#mini");
  node.innerHTML = out;
  node.querySelectorAll("[data-nav]").forEach(b => b.onclick = () => {
    state.cursor = addMonths(state.cursor, parseInt(b.dataset.nav,10)); renderAll();
  });
  node.querySelectorAll("[data-day]").forEach(b => b.onclick = () => {
    const [y,m,dd] = b.dataset.day.split("-").map(Number);
    state.cursor = new Date(y, m-1, dd); renderAll();
  });
}

/* ════════════════════════════════════════════════════════════════════════
   6. rendering — views
   ════════════════════════════════════════════════════════════════════════ */
function chipHtml(occ, cls){
  const ev = occ.event, cals = ev.calendar_ids.map(calById).filter(Boolean);
  const c1 = cals[0] ? cals[0].color : "#888";
  const c2 = cals[1] ? cals[1].color : c1;
  const multi = cals.length > 1;
  const time = occ.all_day ? "" : `<span class="t">${fmtTime(occ.start)}</span> `;
  const badges = [];
  if (occ.source === "task") badges.push(`<span class="badge-src ${occ.refs.task_status === "done" ? "" : ""}">task</span>`);
  if (occ.source === "orchestration") badges.push('<span class="badge-src">run</span>');
  if (occ.source === "meet") badges.push('<span class="badge-src">meet</span>');
  if (occ.source === "external") badges.push('<span class="badge-src">ics</span>');
  const dots = multi ? `<span class="dots">${cals.slice(0,3).map(c => `<i style="background:${c.color}"></i>`).join("")}</span>` : "";
  const past = occ.end < new Date(state.now) ? " past" : "";
  return `<button class="chip ${multi ? "multi" : ""} ${cls || ""}${past}"
      style="--cc:${c1};--cc2:${c2}" data-key="${occ.key}"
      title="${esc(ev.title)} · ${esc(cals.map(c => c.name).join(" + "))}">
      ${time}<b style="font-weight:600">${esc(ev.title)}</b>${badges.length ? `<span class="badges">${badges.join("")}</span>` : ""}${dots}
    </button>`;
}

function renderHeader(range){
  $("#range-label").textContent = range;
  document.querySelectorAll("#view-switch button").forEach(b => {
    b.setAttribute("aria-selected", String(b.dataset.view === state.view));
  });
}

function renderMonth(){
  const c = state.cursor;
  const gridStart = startOfWeek(new Date(c.getFullYear(), c.getMonth(), 1));
  renderHeader(`${MON[c.getMonth()]} ${c.getFullYear()}`);
  const gridEnd = addDays(gridStart, 42);
  const occs = occurrencesBetween(gridStart, gridEnd);
  const byDay = {};
  occs.forEach(o => {
    const span = Math.max(1, Math.ceil((startOfDay(o.end) - startOfDay(o.start)) / DAY) || 1);
    for (let i = 0; i < span; i++){
      const d = addDays(o.start, i);
      const k = dateKey(d);
      (byDay[k] = byDay[k] || []).push(o);
    }
  });

  let html = '<div class="month"><div class="month-head">' + DOW.map(d => `<div>${d}</div>`).join("") + "</div>";
  html += '<div class="month-body">';
  for (let i = 0; i < 42; i++){
    const d = addDays(gridStart, i);
    const other = d.getMonth() !== c.getMonth();
    const today = sameDay(d, new Date());
    const items = (byDay[dateKey(d)] || []).sort((a,b) => {
      if (a.all_day !== b.all_day) return a.all_day ? -1 : 1;
      return a.start - b.start;
    });
    const shown = items.slice(0, 3), extra = items.length - shown.length;
    html += `<div class="mcell ${other ? "other" : ""} ${today ? "today" : ""}" data-day="${dateKey(d)}">
      <button class="clickzone" data-create="${dateKey(d)}" aria-label="Create event on ${dateKey(d)}"></button>
      <span class="num">${d.getDate()}</span>
      <div style="position:relative;z-index:1;display:flex;flex-direction:column;gap:2px">
        ${shown.map(o => o.all_day && o.end.getDate() !== o.start.getDate()
            ? chipHtml(o) : chipHtml(o)).join("")}
        ${extra > 0 ? `<button class="more" data-more="${dateKey(d)}">+${extra} more…</button>` : ""}
      </div>
    </div>`;
  }
  html += "</div></div>";
  $("#view").innerHTML = html;

  $("#view").querySelectorAll("[data-create]").forEach(b => b.onclick = (e) => {
    e.stopPropagation();
    const [y,m,dd] = b.dataset.create.split("-").map(Number);
    openEventEditor(null, new Date(y, m-1, dd, 9, 0));
  });
  $("#view").querySelectorAll("[data-more]").forEach(b => b.onclick = (e) => {
    e.stopPropagation();
    const [y,m,dd] = b.dataset.more.split("-").map(Number);
    state.cursor = new Date(y, m-1, dd); state.view = "day"; renderAll();
  });
  bindChips();
}

function laneLayout(occs){
  // simple greedy lane assignment for overlapping timed events of one day
  const sorted = occs.slice().sort((a,b) => a.start - b.start || b.end - a.end);
  const lanes = [];
  sorted.forEach(o => {
    let placed = false;
    for (let i = 0; i < lanes.length; i++){
      if (lanes[i] <= o.start){ lanes[i] = o.end; o._lane = i; placed = true; break; }
    }
    if (!placed){ o._lane = lanes.length; lanes.push(o.end); }
  });
  return { items: sorted, lanes: Math.max(1, lanes.length) };
}

function renderTimeGrid(days){
  const c = state.cursor;
  const cols = days.length;
  // Week -> the Monday of the cursor's week. Day -> the cursor itself.
  const gridStart = cols === 1 ? startOfDay(c) : startOfWeek(c);
  renderHeader(cols === 7
    ? `${MON[gridStart.getMonth()]} ${gridStart.getFullYear()} · week of ${gridStart.getDate()}`
    : fmtDay(c));

  const from = startOfDay(gridStart), to = addDays(from, cols);
  const occs = occurrencesBetween(from, to);
  const timedByDay = {}, allDayByDay = {};
  occs.forEach(o => {
    const k = dateKey(o.start);
    if (o.all_day) (allDayByDay[k] = allDayByDay[k] || []).push(o);
    else (timedByDay[k] = timedByDay[k] || []).push(o);
  });

  const min5 = 5*MIN;
  let html = "";
  html += '<div class="week-head"><div class="corner"></div>';
  for (let i = 0; i < cols; i++){
    const d = addDays(gridStart, i);
    html += `<div class="day-head ${sameDay(d, new Date()) ? "today" : ""}">
      <div class="dow">${DOW[i]}</div><div class="num">${d.getDate()}</div></div>`;
  }
  html += "</div>";

  const hasAllDay = Object.keys(allDayByDay).length > 0;
  if (hasAllDay){
    html += '<div class="allday-row"><div class="label">all day</div>';
    for (let i = 0; i < cols; i++){
      const d = addDays(gridStart, i);
      const items = (allDayByDay[dateKey(d)] || []);
      html += `<div class="allday-cell">${items.map(o => `<button class="chip"
        style="--cc:${primaryCal(o.event).color}" data-key="${o.key}">${esc(o.event.title)}</button>`).join("")}</div>`;
    }
    html += "</div>";
  }

  html += '<div class="scroll" id="gridscroll"><div class="grid" style="grid-template-columns:56px repeat(' + cols + ',1fr)">';
  html += '<div class="hours">';
  for (let h = 0; h < 24; h++) html += `<div class="hour-lab">${pad2(h)}:00</div>`;
  html += "</div>";

  for (let i = 0; i < cols; i++){
    const d = addDays(gridStart, i);
    const weekend = d.getDay() === 0 || d.getDay() === 6;
    html += `<div class="day-col ${weekend ? "weekend" : ""}" data-day="${dateKey(d)}">`;
    // `top` is explicit: an absolutely positioned sibling with `top:auto` sits at
    // the static position, so every slot (and every hour line) collapsed at the
    // top of the column.
    for (let h = 0; h < 24; h++) html += `<div class="slot" style="top:${h*44}px" data-create="${dateKey(d)}" data-hour="${h}"></div>`;

    const dayStart = startOfDay(d);
    const lay = laneLayout((timedByDay[dateKey(d)] || []));
    lay.items.forEach(o => {
      const top = ((o.start - dayStart) / HOUR) * 44;
      const height = Math.max(18, ((o.end - o.start) / HOUR) * 44 - 2);
      const w = 100 / lay.lanes, left = o._lane * w;
      const cal = primaryCal(o.event);
      html += `<div class="block" data-key="${o.key}" style="top:${top}px;height:${height}px;
        left:calc(${left}% + 2px);width:calc(${w}% - 4px);--cc:${cal.color}"
        title="${esc(o.event.title)} · ${fmtTimeRange(o.start, o.end)}">
        <div class="ttl">${esc(o.event.title)}</div>
        <div class="t">${fmtTimeRange(o.start, o.end)}</div>
        ${o.read_only ? "" : '<div class="resize" title="Resize"></div>'}
      </div>`;
    });
    html += `<div class="nowline" data-now="${dateKey(d)}" hidden></div>`;
    html += "</div>";
  }
  html += "</div></div>";
  $("#view").innerHTML = html;

  $("#view").querySelectorAll("[data-create]").forEach(b => b.onclick = () => {
    const [y,m,dd] = b.dataset.create.split("-").map(Number);
    openEventEditor(null, new Date(y, m-1, dd, parseInt(b.dataset.hour,10), 0));
  });
  bindChips(() => true);
  const sc = $("#gridscroll");
  if (sc) sc.scrollTop = 7.5*44;
  updateNowLine();
}

function renderAgenda(){
  const from = startOfDay(state.cursor), to = addDays(from, 30);
  renderHeader(`Agenda · ${fmtShort(from)} → ${fmtShort(addDays(to,-1))}`);
  const occs = occurrencesBetween(from, to);
  const byDay = {};
  occs.forEach(o => { const k = dateKey(o.start); (byDay[k] = byDay[k] || []).push(o); });

  let html = '<div class="agenda">';
  if (!occs.length) html += '<div class="empty">Nothing scheduled in the next 30 days.</div>';
  for (let i = 0; i < 30; i++){
    const d = addDays(from, i);
    const items = byDay[dateKey(d)];
    if (!items) continue;
    html += `<div class="ag-day ${sameDay(d, new Date()) ? "today" : ""}">
      <h4>${sameDay(d, new Date()) ? "Today · " : ""}${fmtDay(d)}<span class="line"></span></h4>`;
    items.sort((a,b) => (a.all_day === b.all_day) ? a.start - b.start : (a.all_day ? -1 : 1))
      .forEach(o => {
        const cals = o.event.calendar_ids.map(calById).filter(Boolean);
        html += `<div class="ag-row" data-key="${o.key}">
          <div class="ag-time">${o.all_day ? "All day" : fmtTimeRange(o.start, o.end)}</div>
          <div class="ag-main">
            <div class="ag-title">
              <span style="width:3px;height:15px;border-radius:2px;background:${(cals[0]||{}).color};display:inline-block"></span>
              ${esc(o.event.title)}
              ${o.source === "task" ? '<span class="badge-src">task</span>' : ""}
              ${o.source === "orchestration" ? '<span class="badge-src">run</span>' : ""}
              ${o.source === "meet" ? '<span class="badge-src">meet</span>' : ""}
              ${o.source === "external" ? '<span class="badge-src">ics</span>' : ""}
              ${o.read_only ? '<span class="tag ro">read-only</span>' : ""}
            </div>
            <div class="ag-sub">${esc(o.event.location || o.event.description || "")}</div>
            <div class="ag-cal">${cals.map(c => `<i style="background:${c.color}"></i>${esc(c.name)}`).join(" · ")}</div>
          </div>
        </div>`;
      });
    html += "</div>";
  }
  html += "</div>";
  $("#view").innerHTML = html;
  bindChips();
}

function bindChips(){
  const all = occurrencesBetween(addDays(startOfDay(state.cursor), -400), addDays(startOfDay(state.cursor), 400), { includeHidden:true });
  const map = new Map(all.map(o => [o.key, o]));
  document.querySelectorAll(".chip[data-key], .block[data-key], .ag-row[data-key]").forEach(node => {
    node.addEventListener("click", e => {
      e.stopPropagation();
      const occ = map.get(node.dataset.key);
      if (occ) openDetail(occ, e.clientX, e.clientY);
    });
  });
}

function renderAll(){
  renderSidebar(); renderMini(); renderBell();
  if (state.view === "month") renderMonth();
  else if (state.view === "week") renderTimeGrid([0,1,2,3,4,5,6]);
  else if (state.view === "day") renderTimeGrid([0]);
  else renderAgenda();
  renderNotifPanel();
}

/* ════════════════════════════════════════════════════════════════════════
