      <span aria-hidden="true">🔔</span>
      <span class="badge" id="notif-badge" hidden>0</span>
    </button>
    <button class="btn primary" id="btn-new">+ New event</button>
  </div>

  <aside>
    <button class="create" id="btn-create"><span class="plus">+</span> Create</button>
    <div class="mini" id="mini"></div>
    <div>
      <div class="section-title">My calendars</div>
      <div class="cal-list" id="cal-list"></div>
      <button class="cal-row" id="btn-add-cal" style="color:var(--primary);font-weight:600">
        <span style="width:14px;text-align:center">+</span> Add calendar
      </button>
    </div>
    <div>
      <div class="section-title">Other calendars</div>
      <div class="cal-list" id="cal-list-other"></div>
    </div>
    <div class="spacer"></div>
    <details class="help">
      <summary>About this prototype</summary>
      <ul>
        <li>Open a cell to create an event; click a chip for details.</li>
        <li><b>Work · Personal · Team</b> are editable calendars. <b>codx-junior</b> is a read-only
          projection of tasks, runs and meets.</li>
        <li>“Sprint 42 review” lives in <b>two</b> calendars: the chip shows a two-tone bar and both dots.</li>
        <li>Reminders fire from the <b>simulated clock</b>: use ❚❚ / ⏭ next.</li>
        <li>Keys: <kbd>n</kbd> new · <kbd>t</kbd> today · <kbd>m</kbd><kbd>w</kbd><kbd>d</kbd><kbd>a</kbd>
          views · <kbd>←</kbd><kbd>→</kbd> move · <kbd>Esc</kbd> close.</li>
        <li>Data is demo data kept in localStorage. <button class="btn ghost" id="btn-reset"
          style="padding:0;font-size:11px;color:var(--error);text-decoration:underline">Reset demo data</button></li>
      </ul>
    </details>
  </aside>

  <main id="view"></main>
</div>

<div id="detail" role="dialog" aria-label="Event details"></div>

<div class="backdrop" id="backdrop">
  <div class="modal" id="modal" role="dialog" aria-modal="true"></div>
</div>

<div id="notif-panel" role="dialog" aria-label="Notifications"></div>

<div id="toasts" aria-live="polite"></div>
<div class="sr" id="sr-status" aria-live="polite"></div>

<script>
"use strict";
/* ════════════════════════════════════════════════════════════════════════
   0. tiny date layer
   The prototype stores NAIVE LOCAL iso strings ("2026-02-10T09:00") so the
   demo is stable in any timezone. The real API stores UTC + the calendar's
   timezone and returns occurrences (analysis §8).
   ════════════════════════════════════════════════════════════════════════ */
const MIN = 60000, HOUR = 3600000, DAY = 86400000;
const DOW = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
const DOW_LONG = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
const MON = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const pad2 = n => String(n).padStart(2, "0");
const pdate = iso => iso ? new Date(iso) : null;                 // naive-local iso -> Date
function isoLocal(d){
  return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}T${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
}
const dateKey = d => `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`;
const startOfDay = d => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const addDays = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate()+n, d.getHours(), d.getMinutes());
const addMonths = (d, n) => new Date(d.getFullYear(), d.getMonth()+n, 1);
function startOfWeek(d){ const s = startOfDay(d); const w = (s.getDay()+6)%7; return addDays(s, -w); }
const sameDay = (a,b) => a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate();
const daysBetween = (a,b) => Math.round((startOfDay(b) - startOfDay(a))/DAY);
function fmtTime(d){ return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`; }
function fmtTimeRange(a,b){ return `${fmtTime(a)} – ${fmtTime(b)}`; }
function fmtDay(d){ return `${DOW_LONG[(d.getDay()+6)%7]}, ${d.getDate()} ${MON[d.getMonth()]} ${d.getFullYear()}`; }
function fmtShort(d){ return `${DOW[(d.getDay()+6)%7]} ${d.getDate()} ${MON[d.getMonth()].slice(0,3)}`; }

/* ════════════════════════════════════════════════════════════════════════
   1. demo data  (mirrors design/06-calendar/03-fixtures/calendar-fixture.json)
   ════════════════════════════════════════════════════════════════════════ */
const STORE_KEY = "codx-calendar-prototype-v2";

function seed(){
  const today = startOfDay(new Date());
  const now = new Date();
  const at = (dayOffset, h, m=0, durMin=60) => {
    const s = new Date(today.getFullYear(), today.getMonth(), today.getDate()+dayOffset, h, m);
    const e = new Date(s.getTime() + durMin*MIN);
    return { start: isoLocal(s), end: isoLocal(e) };
  };
  const soon = new Date(now.getTime() + 9*MIN);
  soon.setSeconds(0,0);
  const soonEnd = new Date(soon.getTime() + 30*MIN);

  const calendars = [
    { id:"cal_work",     name:"Work",              color:"#CC0099", kind:"personal", read_only:false, visible:true,
      default_reminders:[{channel:"popup",minutes_before:10}] },
    { id:"cal_personal", name:"Personal",          color:"#4696DC", kind:"personal", read_only:false, visible:true,
      default_reminders:[{channel:"popup",minutes_before:30}] },
    { id:"cal_team",     name:"Team — Platform",   color:"#3CB450", kind:"team",     read_only:false, visible:true,
      default_reminders:[{channel:"popup",minutes_before:10}] },
    { id:"cal_codx",     name:"codx-junior",       color:"#FFB428", kind:"system",   read_only:true,  visible:true,
      default_reminders:[] },
    { id:"cal_ics",      name:"Holidays (ICS)",    color:"#7C5CFF", kind:"external", read_only:true,  visible:false,
      default_reminders:[] }
  ];

  const ev = (o) => Object.assign({
    calendar_ids:["cal_work"], description:"", location:"", all_day:false, recurrence:null,
    reminders:[], status:"confirmed", visibility:"default", source:"native", refs:{},
    guests:[], created_by:"alice", revision:1
  }, o);

  // Recurring series START IN THE PAST, like a real calendar: a series that only
  // begins today would leave every previous month empty and would hide the fact
  // that occurrences (not events) are what the grid renders.
  const seriesStart = (dayOffset, h, m, durMin) => {
    const s = new Date(today.getFullYear(), today.getMonth(), today.getDate()+dayOffset, h, m);
    return { start: isoLocal(s), end: isoLocal(new Date(s.getTime() + durMin*MIN)) };
  };
  const standup = seriesStart(-42, 9, 15, 15);
  const retro = seriesStart(-21, 15, 0, 60);

  const events = [
    ev({ id:"evt_standup", calendar_ids:["cal_team","cal_work"], title:"Daily standup",
         start:standup.start, end:standup.end,
         location:"Meet · platform", guests:["marta","jordi"], source:"meet",
         refs:{ meet_id:"9f2a41" }, reminders:[{channel:"popup",minutes_before:5}],
         recurrence:{ rrule:"FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR;UNTIL:" + isoLocal(addDays(today,45)).replace(/[-:]/g,"").slice(0,8) + "T235959Z" } }),

    ev({ id:"evt_spec", calendar_ids:["cal_work"], title:"Spec review — calendar manager",
         start:isoLocal(soon), end:isoLocal(soonEnd),
         description:"Walk through storage + reminders sections before M0.",
         location:"Meet /meet/9f2a", guests:["marta"],
         reminders:[{channel:"popup",minutes_before:15},{channel:"popup",minutes_before:0}] }),

    ev({ id:"evt_sprint", calendar_ids:["cal_codx","cal_work"], title:"Sprint 42 review",
         start:at(1,16).start, end:at(1,17).end, source:"task",
         refs:{ chat_id:"chat_7fd2", project_id:"codx-junior-platform", task_status:"doing" },
         description:"Task card in board “Delivery” · column “In progress”.",
         reminders:[{channel:"popup",minutes_before:10}],
         override_color:null }),

    ev({ id:"evt_1on1", calendar_ids:["cal_work","cal_personal"], title:"1:1 with Marta",
         start:at(2,12).start, end:at(2,12,30).end, guests:["marta"],
         description:"Growth plan + Q2 goals.", reminders:[{channel:"popup",minutes_before:10}] }),

    ev({ id:"evt_offsite", calendar_ids:["cal_work"], title:"Team offsite",
         start:at(10,0).start, end:at(12,23,59).end, all_day:true, location:"Girona",
         description:"Two days out of the office.", reminders:[] }),

    ev({ id:"evt_flight", calendar_ids:["cal_personal"], title:"Flight to Lisbon",
         start:at(8,7,30).start, end:at(8,10,5).end, location:"BCN → LIS",
         reminders:[{channel:"popup",minutes_before:180},{channel:"popup",minutes_before:60}] }),

    ev({ id:"evt_due", calendar_ids:["cal_codx"], title:"Fix onboarding copy",
         start:isoLocal(addDays(today,-1))+"T09:00", end:isoLocal(addDays(today,-1))+"T09:30",
         all_day:true, source:"task", refs:{ chat_id:"chat_91ab", task_status:"todo" },
         description:"Due date marker — read-only, managed by the Task Manager." }),

    ev({ id:"evt_run", calendar_ids:["cal_codx"], title:"Run: autonomous-profiles (7 steps)",
         start:at(0,11,30,90).start, end:at(0,11,30,90).end, source:"orchestration",
         refs:{ run_id:"run_a91f", run_status:"running" },
         description:"2/7 steps done · budget 60 % left." }),

    ev({ id:"evt_retro", calendar_ids:["cal_team"], title:"Team retro",
         start:retro.start, end:retro.end, guests:["marta","jordi","ana"],
         reminders:[{channel:"popup",minutes_before:10}],
         recurrence:{ rrule:"FREQ=MONTHLY;INTERVAL=1;UNTIL:" + isoLocal(addDays(today,180)).replace(/[-:]/g,"").slice(0,8) + "T235959Z" } }),

    ev({ id:"evt_release", calendar_ids:["cal_work","cal_codx"], title:"Release v2.4 window",
         start:at(5,9,0,180).start, end:at(5,9,0,180).end, source:"task",
         refs:{ chat_id:"chat_3c11", task_status:"todo" },
         description:"Freeze + smoke tests. Read-only: change the task to move it." }),

    ev({ id:"evt_holiday", calendar_ids:["cal_ics"], title:"Bank holiday",
         start:isoLocal(addDays(today,14))+"T00:00", end:isoLocal(addDays(today,15))+"T00:00",
         all_day:true, source:"external", description:"Imported from an ICS feed (read-only)." })
  ];

  const notifications = [
    { id:"n1", kind:"system", title:"Task moved to In progress", at:Date.now()-25*MIN,
      body:"“Sprint 42 review” · board Delivery", read:false },
    { id:"n2", kind:"system", title:"Run completed", at:Date.now()-3*HOUR,
      body:"Orchestration run “wiki-refresh” finished · 4 steps, 1.2 cxjcoins", read:true }
  ];

  return { calendars, events, notifications, delivered:{}, snoozes:{} };
}

/* ════════════════════════════════════════════════════════════════════════
   2. state
   ════════════════════════════════════════════════════════════════════════ */
const state = {
  view: "month",
  cursor: startOfDay(new Date()),
  now: Date.now(),
  speed: 60,             // 60× so reminders are observable; 0 = paused
  calendars: [], events: [], notifications: [],
  delivered: {}, snoozes: {},
  detail: null, editing: null, notifTab: "all", notifOpen: false
};

const $ = s => document.querySelector(s);
const el = (tag, cls, html) => { const n = document.createElement(tag); if (cls) n.className = cls; if (html != null) n.innerHTML = html; return n; };
const esc = s => String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));

function load(){
  let data = null;
  try { data = JSON.parse(localStorage.getItem(STORE_KEY) || "null"); } catch(e){ data = null; }
  if (!data || !data.calendars) data = seed();
  state.calendars = data.calendars;
  state.events = data.events;
  state.notifications = data.notifications || [];
  state.delivered = data.delivered || {};
  state.snoozes = data.snoozes || {};
}
function save(){
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify({
      calendars: state.calendars, events: state.events,
      notifications: state.notifications.slice(0,60),
      delivered: state.delivered, snoozes: state.snoozes
    }));
  } catch(e){ /* quota: prototype only */ }
}
const calById = id => state.calendars.find(c => c.id === id) || null;
const isVisible = ev => ev.calendar_ids.some(id => { const c = calById(id); return c && c.visible; });
const primaryCal = ev => calById(ev.calendar_ids[0]) || { color:"#888", name:"—" };

/* ════════════════════════════════════════════════════════════════════════
   3. recurrence + occurrence expansion  (bounded, prototype-grade)
   ════════════════════════════════════════════════════════════════════════ */
function parseRRule(str){
  const out = { freq:"DAILY", interval:1, byday:null, until:null, count:null };
  if (!str) return out;
  const map = { FREQ:v=>out.freq=v, INTERVAL:v=>out.interval=Math.max(1,parseInt(v,10)||1),
                BYDAY:v=>out.byday=v.split(","), UNTIL:v=>out.until=v, COUNT:v=>out.count=parseInt(v,10), };
  str.split(";").forEach(part => { const [k,v] = part.split("="); if (map[k]) map[k](v); });
  return out;
}
const WD = { SU:0, MO:1, TU:2, WE:3, TH:4, FR:5, SA:6 };

function eventOccurrences(ev, rangeStart, rangeEnd){
  const s0 = pdate(ev.start), e0 = pdate(ev.end);
  if (!s0 || !e0) return [];
  const dur = Math.max(MIN, e0 - s0);
  const out = [];
  const push = (start) => out.push({
    key: ev.id + "|" + isoLocal(start),
    event: ev, start, end: new Date(start.getTime() + dur),
    calendar_ids: ev.calendar_ids, source: ev.source, refs: ev.refs || {},
    all_day: !!ev.all_day, read_only: ev.calendar_ids.every(id => (calById(id)||{}).read_only)
  });

  if (!ev.recurrence || !ev.recurrence.rrule){
    if (s0 < rangeEnd && e0 > rangeStart) push(s0);
    return out;
  }

  const rule = parseRRule(ev.recurrence.rrule);
  const until = rule.until
    ? new Date(+rule.until.slice(0,4), +rule.until.slice(4,6)-1, +rule.until.slice(6,8), 23, 59)
    : null;
  // Walk day by day over the window (+alignment), the matcher is order-independent.
  const from = Math.max(startOfDay(s0).getTime(), rangeStart.getTime() - dur - 32*DAY);
  const to   = Math.min(rangeEnd.getTime(), until ? until.getTime() : rangeEnd.getTime());
  let generated = 0, guard = 0;
  for (let t = from; t <= to && guard < 1200; t += DAY, guard++){
    const d = new Date(t);
    const diff = daysBetween(s0, d);
    if (diff < 0) continue;
    const dow = (d.getDay()+6)%7;                       // 0 = Monday
    let hit = false;
    if (rule.freq === "DAILY")       hit = diff % rule.interval === 0;
    else if (rule.freq === "WEEKLY") hit = Math.floor(diff/7) % rule.interval === 0 &&
                                            (!rule.byday || rule.byday.includes(Object.keys(WD).find(k => WD[k] === d.getDay())));
    else if (rule.freq === "MONTHLY"){ const md = (d.getFullYear()-s0.getFullYear())*12 + (d.getMonth()-s0.getMonth());
                                        hit = md % rule.interval === 0 && d.getDate() === s0.getDate(); }
    if (!hit) continue;
    generated++;
    if (rule.count && generated > rule.count) break;
    const start = new Date(d.getFullYear(), d.getMonth(), d.getDate(), s0.getHours(), s0.getMinutes());
    const end = new Date(start.getTime() + dur);
    if (start < rangeEnd && end > rangeStart) push(start);
  }
  return out;
}

function occurrencesBetween(from, to, opts){
  const includeHidden = opts && opts.includeHidden;
  let occs = [];
  for (const ev of state.events){
    if (!includeHidden && !isVisible(ev)) continue;
    occs = occs.concat(eventOccurrences(ev, from, to));
  }
  return occs.sort((a,b) => a.start - b.start);
}

/* ════════════════════════════════════════════════════════════════════════
   4. notifications + reminders
   ════════════════════════════════════════════════════════════════════════ */
function pushNotification(n){
  state.notifications.unshift(Object.assign({ id:"n_" + Math.random().toString(36).slice(2,9),
    at:Date.now(), read:false, kind:"system" }, n));
  if (state.notifications.length > 80) state.notifications.length = 80;
  renderBell(); renderNotifPanel(); save();
}
const unreadCount = () => state.notifications.filter(n => !n.read).length;

function renderBell(){
  const badge = $("#notif-badge"), n = unreadCount();
  badge.hidden = n === 0;
  badge.textContent = n > 99 ? "99+" : String(n);
}

function remindersOf(ev, occ){
  if (occ.read_only) return ev.reminders || [];
  const list = (ev.reminders || []).slice();
  if (!list.length){
    const cal = primaryCal(ev);
    (cal.default_reminders || []).forEach(r => list.push(r));
  }
  return list;
}

// A trigger older than this is reported as "missed" in the notification centre
// instead of popping a toast: analysis §7.2 — the centre is the record, the popup
// is for the present. Without it, catching up after a closed tab showed a storm.
const MISSED_AFTER_MS = 10*MIN;

/** Fires every simulated minute. Mirrors the server tick (analysis §7). */
function checkReminders(catchUpMs){
  const now = state.now;
  const lookBack = catchUpMs || 0;
  const occs = occurrencesBetween(new Date(now - 6*HOUR), new Date(now + 3*DAY), { includeHidden:true });
  for (const occ of occs){
    const keys = [];
    for (const r of remindersOf(occ.event, occ)){
      const trig = occ.start.getTime() - (r.minutes_before||0)*MIN;
      const key = `${occ.event.id}|${isoLocal(occ.start)}|${r.minutes_before}`;
      if (state.delivered[key]) continue;
      if (trig <= now && trig >= now - lookBack){
        keys.push({ key, r, missed: (now - trig) > MISSED_AFTER_MS });
      }
    }
    // snnooze re-fires
    const skey = `${occ.event.id}|${isoLocal(occ.start)}`;
    if (state.snoozes[skey] && state.snoozes[skey].at <= now){
      delete state.snoozes[skey];
      fireReminder(occ, { minutes_before:0, snoozed:true });
    }
    for (const { key, r, missed } of keys){
      state.delivered[key] = new Date(now).toISOString();
      fireReminder(occ, r, missed);
    }
  }
  pruneDelivered();
  save();
}

function pruneDelivered(){
  const limit = Date.now() - 30*DAY;
  Object.keys(state.delivered).forEach(k => {
    if (new Date(state.delivered[k]).getTime() < limit) delete state.delivered[k];
  });
}

function fireReminder(occ, r, missed){
  const ev = occ.event;
  const when = occ.all_day ? "all day" : fmtTimeRange(occ.start, occ.end);
  pushNotification({
    kind:"reminder", title:ev.title, body:`${when} · ${primaryCal(ev).name}`,
    eventId:ev.id, occurrenceKey:occ.key, minutesBefore:r.minutes_before, missed:!!missed
  });
  if (!missed) showToast(occ, r);
  $("#sr-status").textContent = `Reminder: ${ev.title} at ${when}`;
}

function showToast(occ, r){
  const ev = occ.event, cal = primaryCal(ev);
  const when = occ.all_day ? "all day" : fmtTimeRange(occ.start, occ.end);
  const lead = r.snoozed ? "Snoozed reminder" : (r.minutes_before === 0 ? "Starting now" : `In ${r.minutes_before} min`);
  const t = el("div", "toast");
  t.style.setProperty("--cc", cal.color);
  t.innerHTML = `
    <div class="bar" style="background:${cal.color}"></div>
    <div class="in">
      <div class="kick" style="color:${cal.color}">🔔 ${esc(lead)}</div>
      <h4>${esc(ev.title)}</h4>
      <p>${esc(when)}${ev.location ? " · " + esc(ev.location) : ""}</p>
    </div>
    <div class="acts">
      <button class="btn" data-act="open">Open</button>
      <button class="btn" data-act="snooze">Snooze 5 min</button>
      <button class="btn danger" data-act="dismiss">Dismiss</button>
    </div>`;
  const close = () => { t.remove(); };
  t.querySelector('[data-act="open"]').onclick = () => { close(); openDetail(occ); };
  t.querySelector('[data-act="snooze"]').onclick = () => {
    state.snoozes[`${ev.id}|${isoLocal(occ.start)}`] = { at: state.now + 5*MIN };
    pushNotification({ kind:"system", title:"Reminder snoozed 5 min", body:ev.title });
    save(); close();
  };
  t.querySelector('[data-act="dismiss"]').onclick = close;
  $("#toasts").appendChild(t);
  setTimeout(() => { if (t.isConnected) close(); }, 45000);
}

function renderNotifPanel(){
  const p = $("#notif-panel");
  const items = state.notifications.filter(n => state.notifTab === "all" || n.kind === state.notifTab);
  p.innerHTML = `
    <header>
      <h3>Notifications</h3>
      <button class="btn icon" data-act="close" title="Close">✕</button>
    </header>
    <div class="tabs" id="ntabs">
      <button data-tab="all" aria-selected="${state.notifTab==="all"}">All</button>
      <button data-tab="reminder" aria-selected="${state.notifTab==="reminder"}">Reminders</button>
      <button data-tab="system" aria-selected="${state.notifTab==="system"}">System</button>
    </div>
    <div class="nlist">
      ${items.length ? items.map(n => `
        <div class="nitem ${n.read ? "" : "unread"} ${n.missed ? "missed" : ""}" data-id="${n.id}">
          <div class="ico">${n.kind === "reminder" ? "🔔" : "⚡"}</div>
          <div class="txt">
            <div class="ttl">${esc(n.title || "")}${n.missed ? ' <span class="tag">missed</span>' : ""}</div>
            <div class="sub">${esc(n.body || "")}</div>
          </div>
          <div class="when">${fmtTime(new Date(n.at))}</div>
        </div>`).join("") : `<div class="empty">No ${state.notifTab === "all" ? "" : state.notifTab + " "}notifications</div>`}
    </div>
    <div class="nfooter">
      <button class="btn" data-act="readall">Mark all read</button>
      <button class="btn danger" data-act="clear">Clear</button>
    </div>`;

  p.querySelector('[data-act="close"]').onclick = () => toggleNotif(false);
  p.querySelectorAll("#ntabs button").forEach(b => b.onclick = () => { state.notifTab = b.dataset.tab; renderNotifPanel(); });
  p.querySelectorAll(".nitem").forEach(node => node.onclick = () => {
    const n = state.notifications.find(x => x.id === node.dataset.id);
    if (!n) return;
    n.read = true; renderBell(); renderNotifPanel(); save();
    if (n.eventId){
      const ev = state.events.find(e => e.id === n.eventId);
      if (ev) openDetail({ event:ev, start:pdate(ev.start), end:pdate(ev.end),
        calendar_ids:ev.calendar_ids, all_day:ev.all_day, source:ev.source, refs:ev.refs||{},
        read_only:ev.calendar_ids.every(id => (calById(id)||{}).read_only) });
    }
  });
  p.querySelector('[data-act="readall"]').onclick = () => {
    state.notifications.forEach(n => n.read = true); renderBell(); renderNotifPanel(); save();
  };
  p.querySelector('[data-act="clear"]').onclick = () => {
    state.notifications = state.notifications.filter(n => !n.read); renderBell(); renderNotifPanel(); save();
  };
}
function toggleNotif(force){
  state.notifOpen = force === undefined ? !state.notifOpen : force;
  $("#notif-panel").classList.toggle("open", state.notifOpen);
  if (state.notifOpen) renderNotifPanel();
}

